-- نقل سيناريوهات «دليل المواقف» المحبوسة في الشيفرة إلى الجدول المدقَّق
-- ===========================================================================
-- اثنا عشر سيناريو يعيش في src/lib/consultant-scenarios.ts ولا صفّ له في
-- جدول consultant_scenarios. ونتيجتان لذلك:
--
-- 1) خارج التدقيق: التدقيق الشامل الذي أجريناه غطّى الـ111 صفّاً في الجدول.
--    وهذه الاثنا عشر لم يمسسها، ومنها ثلاثة على أخطر المواضيع — الاحتجاز
--    في مركز الترحيل، والتوقيف في المخفر، والوضع غير النظامي — وقد صُحّحت
--    في الشيفرة يدوياً، لكنها تبقى غير قابلة للتحرير من لوحة التحكم ولا
--    تظهر في أي مراجعة مستقبلية للجدول.
--
-- 2) وزن على كل زائر: وجودها في الشيفرة وحدها كان يفرض تنزيل وحدة الـ220KB
--    كاملةً. بعد إدراجها هنا، تصير الشيفرة نسخة احتياطية لا تُنزَّل إطلاقاً
--    في المسار المعتاد.
--
-- النصوص منقولة حرفياً كما هي في الشيفرة اليوم (بما فيها التصحيحات التي
-- أُجريت على سيناريوهات الطوارئ) — هذه هجرة لا إعادة كتابة.
-- ON CONFLICT DO NOTHING: تشغيله مرّتين آمن ولا يدهس أي صفّ قائم.
-- شغّله في Supabase → SQL Editor.

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'daily-driving-license-exchange',
  'استبدال رخصة القيادة الأجنبية (شرط السنة)',
  'high',
  'الأجنبي الحاصل على إقامة في تركيا مُجبر على استبدال رخصته الأجنبية بتركية خلال سنة واحدة. بعد ذلك تُعتبر الرخصة الأجنبية غير صالحة والقيادة بها مخالفة.',
  '["المهلة القانونية: سنة واحدة من تاريخ أول إقامة رسمية في تركيا. بعدها = قيادة بدون رخصة.", "المستندات: رخصة القيادة الأصلية + ترجمة محلفة مصدقة من النوتر + الإقامة أو الكملك + فحص طبي + صور بيومترية.", "التقديم: مديرية المرور (Trafik Tescil Müdürlüğü) أو عبر e-Devlet.", "إذا كانت رخصتك من دولة معترف بها (اتفاقيات ثنائية): استبدال مباشر بفحص طبي فقط.", "إذا لم تكن معترفاً بها: قد يُطلب اجتياز اختبار نظري و/أو عملي.", "ملاحظة: الرخصة الدولية (International Driving Permit) تصلح للسياح فقط — لا تُعفي المقيمين من شرط الاستبدال."]'::jsonb,
  '["الرخصة الأجنبية الأصلية + ترجمة محلفة مصدقة", "بطاقة الإقامة/الكملك", "تقرير فحص طبي (Sağlık Raporu)", "صور بيومترية", "رقم ضريبي"]'::jsonb,
  'رسوم الاستبدال: 1,500-3,000 TL (هرج + بطاقة + فحص طبي). غرامة القيادة بدون رخصة 2026: آلاف الليرات + احتجاز المركبة.',
  'قانون المرور التركي م.38 + لوائح KGM (Karayolları Genel Müdürlüğü). القيادة برخصة أجنبية بعد سنة من الإقامة = مخالفة مرورية + جنائية.',
  'ابدأ إجراءات الاستبدال مبكراً — المعاملة تأخذ أسابيع. لا تؤجل لآخر لحظة. احتفظ بنسخة من رخصتك الأصلية لأنها تُسحب عند الاستبدال.',
  '2026-02',
  '[{"label": "المديرية العامة للأمن", "url": "https://www.egm.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'daily-ptt-services',
  'خدمات بريد PTT للأجانب',
  'safe',
  'PTT (Posta ve Telgraf Teşkilatı) هو البريد الحكومي التركي. يقدم خدمات بريدية + تحويل أموال + دفع فواتير + شيفرة e-Devlet. بنية تحتية أساسية للحياة اليومية.',
  '["خدمات البريد: إرسال واستلام طرود محلية ودولية. كارغو PTT أرخص من الشركات الخاصة للطرود الثقيلة.", "تحويل أموال (Havale/PTT Havale): تحويل نقدي داخلي بدون حساب بنكي — المرسل والمستلم يذهبان لفرع PTT. مفيد لمن ليس لديه حساب بنكي.", "الحوالات الدولية: PTT يتعاون مع Western Union و MoneyGram لاستلام حوالات دولية.", "دفع الفواتير: يمكنك دفع فواتير الكهرباء والماء والغاز والهاتف عبر أي فرع PTT.", "شيفرة e-Devlet: تُستخرج حصرياً من فروع PTT (الخدمة الأهم للأجانب الجدد).", "PTT Kart: بطاقة مسبقة الدفع يمكنك شحنها واستخدامها للتسوق الإلكتروني — بديل لبطاقة الائتمان."]'::jsonb,
  '["الكملك أو جواز السفر أو بطاقة الإقامة (حسب الخدمة)"]'::jsonb,
  'كارغو محلي: يبدأ من 50-100 TL حسب الوزن. تحويل نقدي PTT: عمولة 1-3%. شيفرة e-Devlet: 5-20 TL.',
  'PTT مؤسسة حكومية رسمية. خدماتها مضمونة ومؤمنة.',
  'فروع PTT منتشرة في كل حي — أسهل من البنوك للمعاملات البسيطة. للطرود الدولية: قارن بين PTT و Yurtiçi Kargo و Aras Kargo.',
  '2026-02',
  '[{"label": "بوابة e-Devlet", "url": "https://www.turkiye.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'daily-sworn-translator',
  'الترجمة القانونية الرسمية (Yeminli Tercüman)',
  'medium',
  'المترجم المحلف (Yeminli Tercüman) هو مترجم حلَف اليمين أمام المحكمة ومخوَّل بترجمة الوثائق الرسمية. المحتالون بالترجمة كثيرون وتأثيرهم على ملفات الإقامة كارثي.',
  '["مترجم محلف ≠ أي مترجم. يجب أن يكون مُسجَّلاً رسمياً لدى المحكمة (Adliye) وحلَف اليمين.", "كيف تجد مترجماً محلفاً: اسأل في نقابة المحامين المحلية (Baro)، أو المحكمة (Adliye)، أو اطلب قائمة من النوتر.", "تحقق من صلاحيته: اطلب رقم قيده في المحكمة (Tercüman Sicil No). يمكنك التحقق من UYAP.", "الإجراء: تعطي المترجم المحلف الوثيقة الأصلية → يترجم ويوقّع → تأخذ الترجمة للنوتر ليُصدّق توقيع المترجم.", "تحذير: مكاتب \"ترجمة\" كثيرة حول دوائر الهجرة تقدم ترجمات غير معتمدة — رخيصة لكنها تُرفض من الجهات الرسمية وتُسبب تأخير ملفك.", "ملاحظة: بعض الدوائر تقبل فقط الترجمة المحلفة + تصديق النوتر. ترجمة بدون تصديق نوتر = مرفوضة."]'::jsonb,
  '["الوثيقة الأصلية المراد ترجمتها", "نسخة عن الهوية"]'::jsonb,
  'ترجمة محلفة: 500-2,000 TL/صفحة حسب اللغة والتعقيد. تصديق النوتر: 1,770 TL تقريباً لصفحة واحدة. الإجمالي لوثيقة واحدة: 2,000-4,000 TL.',
  'المترجم المحلف يخضع لرقابة المحكمة. ترجمة خاطئة أو مزورة = مسؤولية جنائية على المترجم. الوثائق المترجمة بدون ختم المحلف + تصديق النوتر لا قيمة قانونية لها.',
  'لا تستخدم مكاتب الترجمة الرخيصة حول دوائر الهجرة — الغالبية غير معتمدة. اسأل المحامي أو النوتر عن مترجم محلف موثوق. احتفظ بالأصل دائماً ولا تسلّمه.',
  '2026-02',
  '[{"label": "بوابة e-Devlet", "url": "https://www.turkiye.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'daily-unhcr-document',
  'وثيقة UNHCR (المفوضية السامية)',
  'high',
  'أهم ما يجب أن تعرفه: المفوضية لم تعد تُسجّل طالبي اللجوء في تركيا منذ العاشر من أيلول 2018. التسجيل صار كلّه لدى إدارة الهجرة التركية. من ينتظر «موعد تسجيل من المفوضية» ينتظر شيئاً لم يعد موجوداً.',
  '["التسجيل يكون لدى مديرية الهجرة في ولايتك (İl Göç İdaresi) وبنفسك — المادة 65/1 من القانون 6458. وإن قدّمت طلبك لدى الشرطة أو عند المنفذ الحدودي أُحيل فوراً إلى الولاية.", "منذ 10 أيلول 2018 توقّفت المفوضية عن تسجيل طالبي الحماية الدولية وعن إجراء تحديد صفة اللاجئ في تركيا، وانتقل ذلك كلّه إلى إدارة الهجرة.", "السوريون مسجَّلون تحت الحماية المؤقتة لدى الدولة التركية مباشرة، لا لدى المفوضية.", "ما تبقّى للمفوضية دور مساند: الإرشاد والمعلومات عبر موقعها، وترشيحات إعادة التوطين التي تجري ضمن المسجَّلين لدى إدارة الهجرة لا خارجهم.", "ما يحميك من الترحيل ليس ورقة من المفوضية، بل صفتك النظامية بعد تقديم طلب الحماية الدولية لدى الولاية، والمادة 55 التي تمنع إصدار قرار الترحيل في حالات محدّدة.", "للمعلومات الرسمية والمحدَّثة راجع صفحة المفوضية للمساعدة في تركيا: help.unhcr.org/turkiye"]'::jsonb,
  '["جواز سفر أو أي وثيقة هوية ولو منتهية الصلاحية", "أي وثائق تدعم طلب الحماية", "ما يثبت عنوان سكنك في الولاية التي تراجعها"]'::jsonb,
  'مراجعة إدارة الهجرة وتقديم طلب الحماية الدولية مجانيان. لا تدفع لأي وسيط يَعِدك بموعد أو بتسريع معاملة.',
  'القانون 6458: المادة 65/1 تقديم طلب الحماية الدولية إلى الولاية بنفسك. المادة 55 الحالات التي لا يجوز فيها إصدار قرار الترحيل. اتفاقية جنيف 1951 وبروتوكول 1967. المفوضية منظمة دولية مستقلة، ولم تعد جهة تسجيل في تركيا منذ 2018.',
  'الادّعاء الذي يبيعه الوسطاء هنا هو «أدبّرلك موعد من المفوضية». لا يوجد موعد تسجيل من المفوضية أصلاً منذ 2018 — من يعرضه عليك يبيعك شيئاً غير موجود.',
  '2026-07',
  '[{"label": "المفوضية — صفحة المساعدة في تركيا", "url": "https://help.unhcr.org/turkiye/"}, {"label": "إدارة الهجرة التركية", "url": "https://www.goc.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'daily-utility-dispute',
  'الاعتراض على فواتير الكهرباء والماء والغاز',
  'safe',
  'إشكالات الفواتير شائعة جداً للمستأجرين العرب في تركيا — فاتورة بمبلغ غير معقول، ديون من المستأجر السابق، أو قطع الخدمة بدون إنذار.',
  '["فاتورة مبالغ فيها: تحقق من قراءة العداد (Sayaç). قارن بين القراءة الفعلية والمسجلة في الفاتورة. إذا وُجد فرق: قدّم اعتراضاً.", "الاعتراض: اتصل بمزود الخدمة (AYEDAŞ/Başkent EDAŞ للكهرباء، İGDAŞ للغاز، İSKİ/ASKİ للماء) أو قدّم طلباً عبر الإنترنت/التطبيق.", "ديون المستأجر السابق: أنت غير مسؤول قانونياً عن ديون مَن سبقك. اطلب نقل العداد باسمك وارفض دفع الديون القديمة.", "قطع الخدمة: لا يحق للشركة قطع الخدمة بدون إنذار رسمي مسبق. إذا قُطعت بدون إنذار: قدّم شكوى لـ EPDK (هيئة تنظيم الطاقة).", "Tüketici Hakem Heyeti: إذا لم تحل المشكلة مباشرة، قدّم شكوى مجانية في لجنة حكم المستهلك في بلديتك.", "ملاحظة: يمكنك متابعة فواتيرك واستهلاكك عبر e-Devlet."]'::jsonb,
  '["الفواتير محل الاعتراض", "عقد الإيجار (لإثبات تاريخ السكن)", "صورة العداد مع القراءة الحالية"]'::jsonb,
  'الاعتراض مجاني. شكوى Tüketici Hakem Heyeti مجانية.',
  'قانون حماية المستهلك + لوائح EPDK (هيئة تنظيم سوق الطاقة). المستأجر غير مسؤول عن ديون المستأجر السابق (قرارات محكمة مستقرة). يحظر قطع الخدمة بدون إنذار رسمي.',
  'عند الانتقال لمنزل جديد: انقل العدادات باسمك فوراً ولا تعتمد على اسم المالك أو المستأجر السابق. صوِّر العداد يوم الانتقال كدليل.',
  '2026-02',
  '[{"label": "هيئة تنظيم سوق الطاقة", "url": "https://www.epdk.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'daily-vehicle-inspection',
  'فحص المركبات والتأمين الإلزامي',
  'medium',
  'كل مركبة في تركيا تحتاج فحصاً دورياً (Araç Muayenesi) وتأمين إلزامي (Trafik Sigortası). الإهمال = غرامات باهظة + منع المركبة.',
  '["الفحص الدوري (Araç Muayenesi): كل سنتين للسيارات الجديدة (أول فحص بعد 3 سنوات من التسجيل)، ثم سنوياً بعد 10 سنوات.", "مراكز الفحص: TÜVTÜRK (المُشغّل الحصري). احجز موعداً عبر tuvturk.com.tr أو ALO 444 0 888.", "التأمين الإلزامي (Zorunlu Trafik Sigortası): إلزامي لكل مركبة مسجلة. يُجدَّد سنوياً. بدونه = غرامة فورية + احتجاز المركبة.", "التأمين الاختياري (Kasko): يغطي أضرار سيارتك + سرقة + كوارث طبيعية. ليس إلزامياً لكنه منصوح به بشدة.", "التحقق من صلاحية الفحص والتأمين: e-Devlet → \"Araç Muayene Sorgulama\" و \"Sigorta Sorgulama\".", "ملاحظة: عدم إجراء الفحص في موعده = غرامة تتصاعد شهرياً (5% زيادة عن كل شهر تأخير)."]'::jsonb,
  '["رخصة المركبة (Araç Ruhsatı)", "وثيقة التأمين الإلزامي الساري", "رخصة القيادة"]'::jsonb,
  'فحص TÜVTÜRK 2026: ~800-1,200 TL (حسب نوع المركبة). تأمين إلزامي سنوي: 3,000-10,000 TL (حسب المركبة والسائق). Kasko: 10,000-30,000+ TL سنوياً.',
  'قانون المرور التركي + لوائح وزارة النقل. غرامة الفحص المتأخر: تتصاعد 5% شهرياً. القيادة بدون تأمين إلزامي: غرامة + احتجاز المركبة فوراً.',
  'سجّل تذكيراً في هاتفك قبل موعد الفحص والتأمين بشهر. قارن أسعار التأمين عبر sigortam.net أو koalay.com — الفروقات كبيرة بين الشركات.',
  '2026-02',
  '[{"label": "بوابة e-Devlet", "url": "https://www.turkiye.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'emergency-detention',
  'احتجاز في مركز الترحيل (GGM / Geri Gönderme Merkezi)',
  'critical',
  'الحجز في مركز الترحيل حجز إداري بقرار من الولاية، لا بقرار قاضٍ. لذلك لا تنتظر أن ينتهي بمرور ساعات — اعترض عليه، وانتبه لمهلة السبعة أيام الخاصة بقرار الترحيل.',
  '["اعترض على قرار الحجز أمام قاضي الصلح الجزائي (Sulh Ceza Hâkimi) — المادة 57/6 من القانون 6458. الاعتراض لا يوقف الحجز، والقاضي يبتّ خلال خمسة أيام وقراره نهائي، ويجوز لك تجديد الطلب إن تغيّرت الظروف.", "الحجز شيء وقرار الترحيل شيء آخر: الطعن على قرار الترحيل أمام المحكمة الإدارية خلال سبعة أيام من التبليغ (المادة 53/3)، ولا تُرحَّل ما دامت الدعوى قائمة.", "اطلب مقابلة محامٍ أو قريب أو كاتب عدل والوصول إلى الهاتف — المادة 59/1(ب) توجب على المركز إتاحة ذلك.", "اطلب مقابلة قنصلية بلدك أو مفوضية اللاجئين — المادة 59/1(ج).", "لا توقّع ولا تبصم على أي ورقة لم تُقرأ عليك بلغتك، واطلب مترجماً قبل التوقيع.", "استمارة العودة الطوعية (Gönüllü Geri Dönüş) تُعامَل رضاً منك بالمغادرة. لا توقّعها تحت الضغط.", "اطلب نسخة من قرار الحجز ومن قرار الترحيل، وسجّل تاريخ التبليغ — منه تبدأ السبعة أيام.", "إن عجزت عن أتعاب المحامي فاطلب المساعدة القضائية من نقابة المحامين — المادة 57/7 توجب توفيرها لمن يطعن في الحجز.", "سجّل التواريخ والأسماء وكل ما يجري."]'::jsonb,
  '["جواز السفر أو أي هوية (إن كانت معك)", "قرار الترحيل (Sınır Dışı Etme Kararı) — اطلب نسخة", "أرقام هواتف محامٍ أو قريب"]'::jsonb,
  'المساعدة القضائية (Adli Yardım) عبر نقابة المحامين لمن لا يقدر على الأتعاب — المادة 57/7. محامي CMK المجاني للمسار الجزائي لا للحجز الإداري، فلا تطلبه بهذا الاسم هنا. أتعاب المحامي الخاص تختلف باختلاف القضية والولاية، ولا يوجد لها سعر معلن.',
  'القانون 6458: المادة 57/2 الحجز الإداري بقرار من الولاية لا من قاضٍ. المادة 57/3 لا يتجاوز الحجز ستة أشهر، ويجوز تمديده ستة أخرى بقرار الولاية إن تعذّر إتمام الترحيل بسبب عدم تعاون الأجنبي. المادة 57/4 على الولاية تقييم استمرار الحجز كل شهر بانتظام. المادة 57/6 الاعتراض أمام قاضي الصلح الجزائي ويبتّ خلال خمسة أيام. المادة 59 خدمات مركز الترحيل. المادة 53/3 سبعة أيام للطعن على الترحيل.',
  'أخطر ما يُقال لك إن ساعات قليلة تكفي ثم تخرج. الحجز الإداري قد يمتدّ شهوراً بقرار إداري، فلا تؤجّل الاعتراض ولا تُضيّع السبعة أيام. وإن أخذوا هاتفك فاحفظ رقم محاميك وقريبك عن ظهر قلب.',
  '2026-02',
  '[{"label": "إدارة الهجرة", "url": "https://www.goc.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'emergency-police-station',
  'تم استدعائي أو احتجازي في مركز الشرطة',
  'high',
  'إذا تم استدعاؤك أو احتجازك في مركز شرطة (Karakol) أو قسم أمن (Emniyet) — لديك حقوق أساسية حتى لو لم تكن تركياً.',
  '["أول حق: محامٍ. اطلب محامياً فوراً قبل الإدلاء بأي إفادة. إذا لم يكن لديك محامٍ = اطلب محامي CMK (مجاني من نقابة المحامين).", "حق الترجمة: إذا لم تكن تتحدث التركية بطلاقة، اطلب مترجماً. إفادة بدون مترجم = يمكن الطعن فيها.", "لا تُجبر على التوقيع: اقرأ (أو اطلب ترجمة) كل وثيقة قبل التوقيع. إذا لم تفهم شيئاً = لا توقّع واطلب شرحاً.", "حقك في الصمت: يحق لك عدم الإجابة على الأسئلة حتى حضور المحامي. هذا حق دستوري.", "مدة التوقيف (Gözaltı) لا تتجاوز أربعاً وعشرين ساعة من لحظة القبض، عدا المدة اللازمة لإرسالك إلى أقرب قاضٍ أو محكمة وهي لا تتجاوز اثنتي عشرة ساعة (المادة 91/1). وفي الجرائم المرتكبة جماعةً وحدها يجوز للنيابة تمديدها كتابةً ثلاثة أيام، كل مرة يوماً واحداً (المادة 91/3).", "انتبه: هذه مدد المسار الجزائي. أما الحجز الإداري في مركز الترحيل فقرار من الولاية وقد يمتدّ ستة أشهر — فاسأل أولاً في أي المسارين أنت.", "اطلب إبلاغ قنصلية بلدك: اتفاقية فيينا م.36 توجب على السلطات إبلاغ القنصلية متى طلبتَ ذلك، وإبلاغك أنت بهذا الحق. اطلبه صراحةً وسجّل أنك طلبته.", "إذا تعرضت لسوء معاملة: سجّل التفاصيل (التاريخ، الوقت، الأسماء) وبلّغ محاميك فوراً. يمكنك أيضاً تقديم شكوى عبر CİMER.", "بعد الإطلاق: احتفظ بنسخة من محضر الاحتجاز (Gözaltı Tutanağı). ستحتاجها إذا أردت الطعن."]'::jsonb,
  '["هويتك (جواز سفر، كملك، إقامة)", "اسم ورقم هاتف محاميك", "رقم قنصلية بلدك في تركيا"]'::jsonb,
  'محامي CMK مجاني في المسار الجزائي. أتعاب المحامي الخاص تختلف باختلاف القضية والولاية، ولا يوجد لها سعر معلن — واحذر من يعرض عليك رقماً ثابتاً قبل أن يرى ملفك.',
  'قانون الإجراءات الجزائية 5271: المادة 91/1 التوقيف لا يتجاوز أربعاً وعشرين ساعة عدا مدة الإرسال إلى القاضي وهي بحدّ أقصى اثنتا عشرة ساعة، والمادة 91/3 التمديد ثلاثة أيام في الجرائم المرتكبة جماعةً وحدها. المادة 95/1 إبلاغ قريب تختاره أنت. المادة 147/1 حقوقك عند أخذ الإفادة ومنها تدوين سبب رفضك التوقيع. المادتان 148/1 و148/3 الإفادة المنتزَعة بالإكراه لا تُقبل دليلاً ولو أعطيتها برضاك. المادة 149 حق الاستعانة بمحامٍ. الدستور م.19 الحرية والأمان الشخصي. اتفاقية فيينا م.36 إبلاغ القنصلية عند طلبك.',
  'أهم شيء: لا تُدلِ بإفادة بدون محامٍ. حتى لو قالوا لك "هذا إجراء روتيني" أو "ستخرج أسرع إذا تعاونت". حقك في الصمت ≠ دليل إدانة.',
  '2026-02',
  '[{"label": "بوابة e-Devlet", "url": "https://www.turkiye.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'emergency-undocumented',
  'بدون أوراق / وضع غير نظامي في تركيا',
  'critical',
  'إذا كنت في تركيا بدون إقامة أو كملك أو أي وثيقة قانونية سارية — وضعك خطير لكن ليس ميؤوساً منه. هناك خيارات قبل أن يتم ضبطك.',
  '["اعرف أولاً إن كنتَ فعلاً في وضع غير نظامي: تجاوز مدة التأشيرة أو الإعفاء يوجب قرار ترحيل إذا زاد على عشرة أيام (المادة 54/1-e)، وكذلك تجاوز مدة إذن الإقامة أكثر من عشرة أيام بلا عذر مقبول (المادة 54/1-g).", "الخيار 1 — طلب الحماية الدولية: يُقدَّم بنفسك إلى الولاية (المادة 65/1)، وإن قدّمته لدى الشرطة أو عند المنفذ أُحيل فوراً إلى الولاية. هذه هي القناة الرسمية، لا أي جهة أخرى.", "الخيار 2 — إذن الإقامة الإنساني (İnsani İkamet İzni): تمنحه الولاية بموافقة المديرية العامة دون اشتراط شروط الأذون الأخرى، ومن حالاته صراحةً من صدر بحقه قرار ترحيل أو حظر دخول (المادة 46/1-b). اسأل عنه بالاسم.", "الخيار 3 — تسوية الوضع بسبب قانوني قائم: زواج، عمل رسمي، دراسة، لمّ شمل. راجع محامياً قبل أن تراجع الإدارة.", "المغادرة بمهلة: من صدر بحقه قرار ترحيل تُمنح له مهلة لا تقلّ عن خمسة عشر يوماً وتصل إلى ثلاثين لمغادرة تركيا، وتُصرَف له وثيقة إذن خروج بلا أي رسم (المادة 56). لكن هذه المهلة لا تُمنح لمن دخل أو خرج بغير الطرق النظامية أو استعمل وثائق مزوّرة أو عُدّ خطراً على النظام العام.", "فرّق بين هذا وبين استمارة العودة الطوعية التي تُعرَض عليك وأنت محتجَز: تلك تُعامَل رضاً منك بالمغادرة وتُسقط ما بيدك من طعن. لا توقّعها تحت الضغط.", "المادة 55 تمنع إصدار قرار الترحيل أصلاً في حالات منها: وجود دلائل جدّية على تعرّضك للإعدام أو التعذيب أو المعاملة اللاإنسانية في بلد الترحيل، والمرض الخطير أو السنّ أو الحمل الذي يجعل السفر خطراً، وضحايا الاتجار بالبشر، وضحايا العنف حتى انتهاء علاجهم. إن انطبقت عليك حالة منها فقُلها صراحةً واطلب تدوينها.", "إن كنت سورياً فقدتَ الكملك فراجع مديرية الهجرة لاستخراج البدل — وهو مجاني بنصّ المادة 22/3 من لائحة الحماية المؤقتة."]'::jsonb,
  '["أي وثيقة هوية متاحة (جواز سفر منتهي، صورة عن الكملك، إلخ)", "أي وثائق تثبت دخولك تركيا بشكل نظامي سابقاً", "وثائق تدعم طلب الحماية (إن وجدت)"]'::jsonb,
  'مراجعة إدارة الهجرة مجانية، ووثيقة إذن الخروج لا تخضع لأي رسم (المادة 56/2). المساعدة القضائية عبر نقابة المحامين لمن لا يقدر على الأتعاب. أتعاب المحامي الخاص تختلف باختلاف القضية والولاية ولا يوجد لها سعر معلن.',
  'القانون 6458: المادة 54/1 بندا (e) و(g) تجاوز التأشيرة أو إذن الإقامة أكثر من عشرة أيام. المادة 46/1-b إذن الإقامة الإنساني لمن صدر بحقه قرار ترحيل أو حظر دخول. المادة 55 الحالات التي لا يجوز فيها إصدار قرار الترحيل. المادة 56 مهلة المغادرة من خمسة عشر إلى ثلاثين يوماً ووثيقة إذن الخروج بلا رسم. المادة 65/1 طلب الحماية الدولية يُقدَّم إلى الولاية بنفسك. المادة 9/3 حظر الدخول لا يتجاوز خمس سنوات، ويجوز رفعه عشر سنوات أخرى عند وجود تهديد جدّي للنظام أو الأمن العام.',
  'أسوأ خيار هو عدم فعل شيء، لكن ثاني أسوأ خيار هو التوقيع على ورقة لا تفهمها ظنّاً أنها تسوية. راجع محامياً أو مؤسسة قانونية قبل أن تُوقّع أي شيء، واطلب دائماً نسخة مما وقّعت.',
  '2026-02',
  '[{"label": "إدارة الهجرة", "url": "https://www.goc.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'family-aile-ikamet',
  'إقامة الأسرة (Aile İkamet İzni) — 2026',
  'medium',
  'إقامة الأسرة تُمنح لأفراد عائلة الأجنبي المقيم في تركيا (الزوج/الزوجة والأطفال تحت 18). الكفيل (المؤمِّن) يجب أن يكون على إقامة سارية لمدة سنة على الأقل ويثبت القدرة المالية.',
  '["الشرط الأول: يجب أن يكون الكفيل (صاحب الإقامة الأصلية) حاصلاً على إقامة سارية منذ سنة على الأقل.", "الشرط المالي: إثبات دخل لا يقل عن الحد الأدنى للأجور × عدد أفراد الأسرة. (الحد الأدنى 2026: ~22,104 TL — عائلة من 4 = ~88,416 TL شهرياً).", "التقديم إلكترونياً عبر e-ikamet.goc.gov.tr — تقديم طلب لكل فرد من أفراد الأسرة.", "تجهيز المستندات: جواز سفر كل فرد + تأمين صحي لكل فرد + دفتر الزواج الرسمي + كشف حساب بنكي.", "دفع الرسوم: رسم بطاقة (Kart Bedeli) 964 TL × عدد الأفراد + رسم الطابع (Harç) حسب الجنسية والمدة.", "الذهاب في الموعد المحدد إلى إدارة الهجرة مع كل أفراد الأسرة لتقديم البيانات البيومترية.", "الانتظار 30-90 يوماً للقرار. خلال الانتظار يحق للعائلة البقاء في تركيا."]'::jsonb,
  '["جواز سفر ساري لكل فرد (صلاحية 60 يوماً بعد مدة الإقامة)", "صور بيومترية (4 لكل فرد)", "دفتر الزواج الرسمي (Evlenme Cüzdanı)", "نسخة إقامة الكفيل السارية", "تأمين صحي لكل فرد من أفراد الأسرة", "كشف حساب بنكي يثبت الدخل الشهري", "عقد إيجار أو سند ملكية", "شهادات ميلاد الأطفال (مترجمة ومصدقة)"]'::jsonb,
  'رسم البطاقة: 964 TL × عدد الأفراد. رسم الطابع: 1,200–3,500 TL لكل فرد حسب الجنسية. التأمين الصحي: 4,000–10,000 TL/سنة لكل فرد. مثال لعائلة من 4: تقريباً 25,000–60,000 TL شاملة كل الرسوم والتأمين.',
  'المادة 34 و35 من قانون الأجانب رقم 6458 (YUKK). إقامة الأسرة مرتبطة بإقامة الكفيل — إذا أُلغيت إقامته تُلغى إقامة الأسرة تلقائياً.',
  'الخطأ الأكثر شيوعاً: التقديم قبل مرور سنة على إقامة الكفيل — الطلب يُرفض تلقائياً. تأكد أيضاً أن دفتر الزواج رسمي (البلدية) وليس عقداً شرعياً فقط.',
  '2026-02',
  '[{"label": "إدارة الهجرة التركية", "url": "https://www.goc.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'student-turkiye-burslari',
  'منح الحكومة التركية (Türkiye Bursları)',
  'safe',
  'Türkiye Bursları هي منح حكومية تركية تقدمها هيئة الأتراك في الخارج (YTB) — تغطي الرسوم الدراسية + السكن + مبلغ شهري + تأمين صحي + تذكرة طيران + دورة لغة تركية مجانية.',
  '["ادخل الموقع الرسمي: turkiyeburslari.gov.tr وأنشئ حساباً.", "التقديم يكون سنوياً — عادة يفتح في يناير/فبراير ويُغلق في مارس.", "ارفع المستندات المطلوبة: شهادات + كشف درجات + رسالة دافع + توصيات.", "في حال القبول المبدئي: ستُدعى لمقابلة (قد تكون أونلاين).", "المنحة تشمل: رسوم دراسية كاملة + سكن جامعي + مبلغ شهري (حسب المرحلة) + تأمين صحي + تذكرة طيران سنوية + سنة لغة تركية مجانية.", "المبالغ الشهرية الرسمية 2025-2026: ليسانس 4,500 TL | ماجستير 6,500 TL | دكتوراه 9,000 TL. (منحة التفوق: ضعف المبلغ). بدل سكن للدراسات العليا: 6,000 TL في إسطنبول وأنقرة، 5,000 TL في باقي الولايات."]'::jsonb,
  '["شهادة الثانوية أو الجامعية (حسب المرحلة)", "كشف الدرجات", "جواز سفر أو وثيقة هوية", "صور شخصية", "رسالة دافع (Motivation Letter)", "رسائل توصية (اختيارية لكن مؤثرة)"]'::jsonb,
  'مجانية بالكامل — لا رسوم تقديم.',
  'المنحة مقدمة من YTB (هيئة الأتراك في الخارج والمجتمعات ذات الصلة). الالتزام بالحضور والنجاح الأكاديمي شرط للاستمرار.',
  'المنافسة شديدة — ركّز على رسالة الدافع واجعلها شخصية وقوية. التقديم مبكراً أفضل. الطلاب العرب يشكلون نسبة كبيرة من المتقدمين — تميّز بمشروعك ونشاطاتك.',
  '2026-02',
  '[{"label": "رئاسة الأتراك في الخارج", "url": "https://www.ytb.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

INSERT INTO consultant_scenarios
  (id, title, risk, description, steps, docs, cost, legal, tip, last_update, sources, is_active)
VALUES (
  'student-work-rights',
  'حق العمل للطالب الأجنبي',
  'medium',
  'حق العمل ليس أوتوماتيكياً للطلاب الأجانب — يحتاج إذن عمل رسمي. القواعد تختلف بين طلاب الليسانس/الدبلوم وطلاب الماجستير/الدكتوراه.',
  '["طلاب الليسانس والدبلوم: يجب إتمام السنة الأولى كاملة قبل التقدم لإذن عمل.", "بعد إتمام السنة الأولى: قدّم طلب إذن عمل عبر وزارة العمل (Çalışma Bakanlığı).", "طلاب الماجستير والدكتوراه: مستثنون من قيود الوقت الجزئي — يمكنهم العمل بدوام كامل بإذن عمل.", "العمل بدون إذن = مخالفة قانونية قد تؤدي لإلغاء الإقامة والترحيل.", "ابحث عن فرص عمل داخل الجامعة (Araştırma Görevlisi / Asistan) — أسهل في الحصول على إذن."]'::jsonb,
  '["وثيقة طالب سارية (Öğrenci Belgesi)", "جواز سفر وإقامة سارية", "عرض عمل من جهة العمل", "طلب إذن عمل من وزارة العمل"]'::jsonb,
  'رسوم إذن العمل للطالب (أجنبي عادي — سنة): 13,538.90 TL (12,574.90 هرج + 964 بطاقة). حاملو الكملك: 5,641.90 TL. الرسوم يتحملها صاحب العمل عادةً.',
  'قانون العمل 4857 + YUKK م.41: الطالب يحتاج إذن عمل رسمي. العمل بدون إذن = غرامة + إمكانية إلغاء الإقامة. طلاب الليسانس: يجب إتمام السنة الأولى أولاً.',
  'إذا كنت تحتاج دخلاً إضافياً أثناء الدراسة: ابحث عن فرص العمل الجزئي داخل الجامعة أو المنح التي تشمل مبلغاً شهرياً (مثل Türkiye Bursları).',
  '2026-02',
  '[{"label": "بوابة إذن العمل", "url": "https://calismaizni.gov.tr"}]'::jsonb,
  true
)
ON CONFLICT (id) DO NOTHING;

-- ═══════════════════════════════════════════════════════════════════════
-- التحقّق — يجب أن يرجع 12 صفاً، والمجموع 123
SELECT id, risk, jsonb_array_length(steps) AS steps_n, left(title, 40) AS title
FROM consultant_scenarios WHERE id IN ('daily-driving-license-exchange', 'daily-ptt-services', 'daily-sworn-translator', 'daily-unhcr-document', 'daily-utility-dispute', 'daily-vehicle-inspection', 'emergency-detention', 'emergency-police-station', 'emergency-undocumented', 'family-aile-ikamet', 'student-turkiye-burslari', 'student-work-rights') ORDER BY id;

SELECT count(*) AS total_scenarios FROM consultant_scenarios;
